import{_ as e,o as d,c as o,ag as r}from"./chunks/framework.B7PviQjB.js";const u=JSON.parse('{"title":"Keyboard shortcuts","description":"Keyboard shortcuts for moving, selecting, editing, and formatting in a sheet.","frontmatter":{"title":"Keyboard shortcuts","description":"Keyboard shortcuts for moving, selecting, editing, and formatting in a sheet.","type":"reference"},"headers":[],"relativePath":"sheets/keyboard-shortcuts.md","filePath":"sheets/keyboard-shortcuts.md"}'),c={name:"sheets/keyboard-shortcuts.md"};function a(i,t,l,n,h,s){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h1><p>Keyboard shortcuts for moving, selecting, editing, and formatting in a sheet.</p><p>Mac keys come first, then Windows and Linux: <code>⌘+C</code> / <code>Ctrl+C</code>. Where only one key is listed, it&#39;s the same on every platform. To see the list in the app, press <code>⌘+/</code> / <code>Ctrl+/</code> in a sheet.</p><h2 id="most-used" tabindex="-1">Most used <a class="header-anchor" href="#most-used" aria-label="Permalink to &quot;Most used&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Copy, cut, paste</td><td><code>⌘+C</code>, <code>⌘+X</code>, <code>⌘+V</code> / <code>Ctrl+C</code>, <code>Ctrl+X</code>, <code>Ctrl+V</code></td></tr><tr><td>Undo</td><td><code>⌘+Z</code> / <code>Ctrl+Z</code></td></tr><tr><td>Redo</td><td><code>⌘+Shift+Z</code> or <code>⌘+Y</code> / <code>Ctrl+Shift+Z</code> or <code>Ctrl+Y</code></td></tr><tr><td>Edit the active cell, keeping its contents</td><td><code>F2</code> or <code>Enter</code></td></tr><tr><td>Fill down</td><td><code>⌘+D</code> / <code>Ctrl+D</code></td></tr><tr><td>Bold</td><td><code>⌘+B</code> / <code>Ctrl+B</code></td></tr><tr><td>Find</td><td><code>⌘+F</code> / <code>Ctrl+F</code></td></tr></tbody></table><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Move the active cell</td><td><code>←</code>, <code>→</code>, <code>↑</code>, <code>↓</code></td></tr><tr><td>Jump to the edge of the data</td><td><code>⌘+←</code> and the other arrows / <code>Ctrl+←</code> and the other arrows</td></tr><tr><td>Move to the next or previous cell</td><td><code>Tab</code> / <code>Shift+Tab</code></td></tr><tr><td>Move down or up inside a selected range</td><td><code>Enter</code> / <code>Shift+Enter</code></td></tr><tr><td>Return to the column where a run of <code>Tab</code> presses started, one row down</td><td><code>Enter</code> after <code>Tab</code></td></tr></tbody></table><h2 id="selection" tabindex="-1">Selection <a class="header-anchor" href="#selection" aria-label="Permalink to &quot;Selection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Select all</td><td><code>⌘+A</code> / <code>Ctrl+A</code></td></tr><tr><td>Extend the selection by one cell</td><td><code>Shift+←</code> and the other arrows</td></tr><tr><td>Select the entire row</td><td><code>Shift+Space</code></td></tr><tr><td>Select the entire column</td><td><code>Ctrl+Space</code> (on a Mac too)</td></tr></tbody></table><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Start typing into the active cell, replacing its contents</td><td>Any letter or number</td></tr><tr><td>Edit the active cell, keeping its contents</td><td><code>F2</code></td></tr><tr><td>Confirm and move down</td><td><code>Enter</code></td></tr><tr><td>Confirm and move right or left</td><td><code>Tab</code> / <code>Shift+Tab</code></td></tr><tr><td>Cancel editing</td><td><code>Escape</code></td></tr><tr><td>Insert a line break while editing</td><td><code>Option+Enter</code> or <code>⌘+Enter</code> / <code>Alt+Enter</code> or <code>Ctrl+Enter</code></td></tr><tr><td>Switch a formula reference between relative and absolute while editing</td><td><code>F4</code></td></tr><tr><td>Clear the selected cells</td><td><code>Delete</code> or <code>Backspace</code></td></tr><tr><td>Fill down</td><td><code>⌘+D</code> / <code>Ctrl+D</code></td></tr><tr><td>Fill right</td><td><code>⌘+R</code> / <code>Ctrl+R</code></td></tr><tr><td>Merge or unmerge the selected cells</td><td><code>⌘+Shift+M</code> / <code>Ctrl+Shift+M</code></td></tr><tr><td>Copy, cut, paste</td><td><code>⌘+C</code>, <code>⌘+X</code>, <code>⌘+V</code> / <code>Ctrl+C</code>, <code>Ctrl+X</code>, <code>Ctrl+V</code></td></tr><tr><td>Clear the copy marquee</td><td><code>Escape</code></td></tr><tr><td>Undo</td><td><code>⌘+Z</code> / <code>Ctrl+Z</code></td></tr><tr><td>Redo</td><td><code>⌘+Shift+Z</code> or <code>⌘+Y</code> / <code>Ctrl+Shift+Z</code> or <code>Ctrl+Y</code></td></tr><tr><td>Toggle the selected checkboxes</td><td><code>Space</code></td></tr><tr><td>Open a dropdown list</td><td><code>Option+↓</code> / <code>Alt+↓</code></td></tr><tr><td>Open the link under the pointer</td><td><code>⌘</code>-click / <code>Ctrl</code>-click</td></tr><tr><td>Open every link in the active cell</td><td><code>Option+Enter</code> / <code>Alt+Enter</code> (not while editing)</td></tr><tr><td>Add a comment to the active cell</td><td><code>⌘+Option+M</code> / <code>Ctrl+Alt+M</code></td></tr><tr><td>Run the query in a data source tab</td><td><code>⌘+Enter</code> / <code>Ctrl+Enter</code></td></tr></tbody></table><p><code>Space</code> and <code>Option+↓</code> / <code>Alt+↓</code> work only on cells with a checkbox or dropdown rule. See <a href="/docs/sheets/data-validation.html">Data validation</a>.</p><p>In the formula bar, use <code>Option+Enter</code> / <code>Alt+Enter</code> for a line break.</p><h2 id="formatting" tabindex="-1">Formatting <a class="header-anchor" href="#formatting" aria-label="Permalink to &quot;Formatting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Bold</td><td><code>⌘+B</code> / <code>Ctrl+B</code></td></tr><tr><td>Italic</td><td><code>⌘+I</code> / <code>Ctrl+I</code></td></tr><tr><td>Underline</td><td><code>⌘+U</code> / <code>Ctrl+U</code></td></tr><tr><td>Strikethrough</td><td><code>⌘+Shift+S</code> / <code>Ctrl+Shift+S</code></td></tr></tbody></table><h2 id="objects" tabindex="-1">Objects <a class="header-anchor" href="#objects" aria-label="Permalink to &quot;Objects&quot;">​</a></h2><p>These work on a selected chart or image.</p><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Delete it</td><td><code>Delete</code> or <code>Backspace</code></td></tr><tr><td>Nudge it</td><td><code>←</code>, <code>→</code>, <code>↑</code>, <code>↓</code></td></tr><tr><td>Deselect it</td><td><code>Escape</code></td></tr></tbody></table><h2 id="view" tabindex="-1">View <a class="header-anchor" href="#view" aria-label="Permalink to &quot;View&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To do this</th><th>Press</th></tr></thead><tbody><tr><td>Find</td><td><code>⌘+F</code> / <code>Ctrl+F</code></td></tr><tr><td>Show or hide the comments panel</td><td><code>⌘+Option+Shift+M</code> / <code>Ctrl+Alt+Shift+M</code></td></tr><tr><td>Show keyboard shortcuts</td><td><code>⌘+/</code> / <code>Ctrl+/</code></td></tr></tbody></table><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li><code>Shift</code> with <code>⌘</code> / <code>Ctrl</code> and an arrow extends the selection by one cell, not to the edge of the data.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/sheets/edit-and-format.html">Edit and format cells</a> for the tasks behind these keys.</li><li><a href="/docs/sheets/formulas.html">Formulas</a> for absolute references with <code>F4</code>.</li><li><a href="/docs/collaborate/comments.html">Comments</a> for discussing a cell with your team.</li></ul>',24)])])}const m=e(c,[["render",a]]);export{u as __pageData,m as default};
